const items = Array.isArray(input.refundItems) ? input.refundItems : [];
const titles = items.map(item => typeof item?.title === "string" ? item.title.trim() : "").filter(Boolean);
const content = typeof input.content === "string" ? input.content : "";
const escapeHtml = value => value.replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" })[char]);
const alreadyIntroduced = content.includes("Thank you for reaching out — we have received your return request.");
const refundContent = titles.length && !alreadyIntroduced
  ? "Thank you for reaching out — we have received your return request for " + titles.map(escapeHtml).join(" &amp; ") + ".<br>"
  : "";
return { refundContent };

