let salesType='none'
if(input.afterSalesOption==='Exchange' || input.afterSalesOption==='Replacement'){
  salesType='exchange'
}else if(input.afterSalesOption==='Refund' || input.afterSalesOption==='Partial refund'){
  salesType='refund'
}else{
  salesType='none'
}

return { salesType: salesType };

let orderScene='';
const paymentTimer = new Date(input.paymentTime).getTime();
const newTimer=Date.now();
const isExpired=(newTimer-paymentTimer) > 90 * 1000 * 60 * 60 * 12;
if(input.disputing){
   orderScene='disputing'
}else if(input.shippingTime){
   orderScene='shipped'
}else if(isExpired){
   orderScene='expired'
}else{
  orderScene='continue'
}
return {
  orderScene:orderScene
}
